from bank_core import *
from diagrams import line_svg

def questions(v=0):
 b=Bank(6,v);a=2+v;k=2+v%3;z=5+v;t='معادلهٔ خط';s='شیب و عرض از مبدأ';u='دستگاه معادله‌های خطی'
 b.n(1,'خواندن شیب در فرم استاندارد',s,f'شیب خط y={k}x−{a} چند است؟',k,'در فرم y=mx+b، ضریب x همان شیب است.',f'diff({k}*x-{a},x)')
 b.n(1,'خواندن عرض از مبدأ علامت‌دار',s,f'عرض از مبدأ خط y={k}x−{a} چند است؟',-a,'عرض از مبدأ، مقدار y در x=0 است و علامتش حفظ می‌شود.',f'({k}*x-{a}).subs(x,0)')
 b.n(1,'جایگذاری طول برای یافتن عرض',t,f'روی خط y={k}x+{a}، اگر x={z} باشد، y چند است؟',k*z+a,'طول داده‌شده را در معادله جایگذاری و سپس عملیات را انجام بده.',f'{k}*{z}+{a}')
 b.n(1,'جایگذاری عرض برای یافتن طول',t,f'روی خط y={k}x+{a}، اگر y={k*z+a} باشد، x چند است؟',z,'پس از کم کردن عرض از مبدأ، بر شیب ناصفر تقسیم کن.',f'({k*z+a}-{a})/{k}')
 b.m(1,'خط افقی و محور موازی',t,f'خط y={a} با کدام محور موازی است؟','محور طول‌ها',['محور عرض‌ها','هیچ‌کدام','هر دو محور'],'در این خط، عرض ثابت است و طول می‌تواند تغییر کند؛ خط افقی است.')
 b.m(1,'خط عمودی و معادله‌اش',t,f'کدام معادله خطی عمودی از نقطهٔ ({a},{z}) می‌گذرد؟',f'x={a}',[f'y={a}',f'y={z}',f'x={z}'],'در خط عمودی، طول همهٔ نقطه‌ها یکسان است.')
 b.tf(1,'عضویت یک نقطه در خط',t,f'نقطهٔ ({a},{k*a+z}) روی خط y={k}x+{z} قرار دارد.',True,'با جایگذاری مختصات نقطه، دو طرف معادله باید برابر شوند.')
 b.n(1,'شیب خط افقی',s,f'شیب خط y={a} چند است؟',0,'با تغییر x، مقدار y عوض نمی‌شود؛ تغییر عرض صفر است.', 'Integer(0)')
 b.m(1,'شیب خط عمودی تعریف‌نشده',s,f'شیب خط x={a} چگونه است؟','تعریف نشده است',['صفر','یک',str(a)],'تغییر طول دو نقطهٔ خط صفر است و تقسیم بر صفر مجاز نیست.')
 b.n(1,'عبور از مبدأ',s,f'اگر خط y={k}x+b از مبدأ بگذرد، b چند است؟',0,'مختصات مبدأ صفر و صفر است؛ آن را در معادله بگذار.', 'Integer(0)')
 b.m(1,'علامت شیب از رفتار خط',s,'اگر با افزایش طول، عرض نقطه‌های یک خط کم شود، شیب چه علامتی دارد؟','منفی',['مثبت','حتماً صفر','همیشه تعریف‌نشده'],'در تغییر طول مثبت، تغییر عرض منفی است؛ نسبت دو تغییر منفی می‌شود.')
 b.n(1,'تعداد جواب یکتای دو خط ناموازی',u,'دو خط در صفحه دقیقاً یک نقطهٔ برخورد دارند؛ دستگاه آن‌ها چند جواب دارد؟',1,'هر جواب مشترک دستگاه، یک نقطهٔ مشترک دو خط است.', 'Integer(1)')
 b.n(2,'استخراج شیب از فرم کلی',s,f'شیب خط 2y−{2*k}x={2*a} چند است؟',k,'ابتدا y را تنها کن؛ ضریب x قبل از این تبدیل، لزوماً شیب نیست.',f'Rational({2*k},2)')
 b.n(2,'عرض از مبدأ از فرم کلی',s,f'عرض از مبدأ خط {k}x+2y={2*z} چند است؟',z,'برای محور عرض‌ها x=0 بگذار و y را پیدا کن.',f'Rational({2*z},2)')
 b.n(2,'شیب از دو نقطه',s,f'خط از ({a},{z}) و ({a+2},{z+2*k}) می‌گذرد؛ شیب چند است؟',k,'تغییر عرض را بر تغییر طول تقسیم کن و ترتیب کم کردن‌ها را یکسان بگیر.',f'({z+2*k}-{z})/({a+2}-{a})')
 b.n(2,'نوشتن خط با شیب و یک نقطه',t,f'خطی با شیب {k} از نقطهٔ ({a},{z}) می‌گذرد؛ عرض از مبدأ آن چند است؟',z-k*a,'نقطه و شیب را در y=mx+b بگذار و b را پیدا کن.',f'{z}-{k}*{a}')
 b.n(2,'طول از مبدأ',t,f'طول نقطهٔ برخورد خط y={k}x−{k*a} با محور طول‌ها چند است؟',a,'در محور طول‌ها y=0 است؛ صفر کردن x مربوط به محور عرض‌هاست.',f'{k*a}/{k}')
 b.n(2,'معادلهٔ موازی از نقطه',s,f'خطی موازی y={k}x+{z} از (0,−{a}) می‌گذرد؛ عرض از مبدأ خط تازه چند است؟',-a,'خط موازی همان شیب را دارد؛ نقطهٔ با طول صفر، عرض از مبدأ را مشخص می‌کند.',f'-{a}')
 b.m(2,'تمایز خطوط موازی و منطبق',u,f'دو خط y={k}x+{a} و y={k}x+{a+1} چه وضعیتی دارند؟','موازی و جدا هستند',['منطبق‌اند','دقیقاً یک نقطهٔ مشترک دارند','عمودند'],'شیب‌ها برابر و عرض از مبدأها متفاوت است؛ خط‌ها جدا و موازی‌اند.')
 b.m(2,'تشخیص دو معادلهٔ یک خط',u,f'معادله‌های y={k}x+{a} و 2y={2*k}x+{2*a} چه وضعیتی دارند؟','یک خط را نمایش می‌دهند',['موازی و جدا هستند','فقط در مبدأ مشترک‌اند','هیچ جوابی ندارند'],'دومی با ضرب همهٔ طرف‌های اولی در دو به دست آمده؛ دستگاه بی‌شمار جواب دارد.')
 x0=a;y0=z
 b.n(2,'حل دستگاه با حذف یک مجهول',u,f'در دستگاه x+y={x0+y0} و x−y={x0-y0}، x چند است؟',x0,'دو معادله را جمع کن تا y حذف شود.',f'({x0+y0}+({x0-y0}))/2')
 b.n(2,'حل دستگاه با جایگذاری',u,f'در دستگاه y=2x+1 و x+y={3*a+1}، y چند است؟',2*a+1,'رابطهٔ y را در معادلهٔ دیگر جایگذاری کن، سپس مقدار y را برگردان.',f'2*(({3*a+1}-1)/3)+1')
 b.n(2,'مدل خطی هزینهٔ ثابت و متغیر',t,f'کرایهٔ ثابت {a} و کرایهٔ هر کیلومتر {k} واحد است؛ هزینهٔ {z} کیلومتر چند واحد است؟',a+k*z,'قسمت ثابت را یک بار و هزینهٔ مسیر را به تعداد کیلومتر حساب کن.',f'{a}+{k}*{z}')
 b.n(2,'خواندن نمودار مدرج خط',s,'عرض از مبدأ خط رسم‌شده را از روی نمودار بخوان.',1+v,'محل برخورد خط با محور y را پیدا کن؛ شمارهٔ خانه‌های محور را با مقیاسش بخوان.', f'Integer({1+v})',diagram=line_svg(1,1+v))
 b.n(3,'خط از دو نقطه با شیب کسری',s,f'خط از (−{a},{z}) و ({a},{z+3}) می‌گذرد؛ شیب چند است؟',F(3,2*a),'تفاضل طول‌ها در عبور از منفی به مثبت جمع فاصله‌هاست.',f'({z+3}-{z})/({a}-(-{a}))')
 b.n(3,'عرض از مبدأ پس از دو نقطه',t,f'خط از (1,{a+k}) و (3,{a+3*k}) می‌گذرد؛ عرض از مبدأ چند است؟',a,'ابتدا شیب را از دو نقطه پیدا کن و سپس یک نقطه را در فرم استاندارد بگذار.',f'{a+k}-(({a+3*k}-{a+k})/(3-1))')
 b.n(3,'محل برخورد دو خط',u,f'طول نقطهٔ برخورد y={k}x+{a} و y=−x+{a+(k+1)*z} چند است؟',z,'در نقطهٔ برخورد، دو مقدار y برابرند؛ معادلهٔ یک‌مجهولی حاصل را حل کن.',f'({a+(k+1)*z}-{a})/({k}+1)')
 b.n(3,'مساحت مثلث خط و محورها',t,f'خط x/{a}+y/{z}=1 با محورها مثلث می‌سازد؛ مساحت آن چند واحد مربع است؟',F(a*z,2),'دو عرض از مبدأِ مثبت، دو ضلع قائمهٔ مثلث را می‌دهند.',f'Rational({a}*{z},2)')
 b.n(3,'مجهول در شرط موازی بودن',s,f'خط‌های 2y−cx={a} و y={k}x+1 موازی‌اند؛ c چند است؟',2*k,'شیب خط اول c/2 است؛ آن را با شیب خط دوم برابر کن.',f'2*{k}')
 b.n(3,'شیب خط عمود',s,f'خطی بر y={k}x+{a} عمود است؛ شیب آن چند است؟',F(-1,k),'برای دو خط غیرعمودیِ عمود، حاصل ضرب شیب‌ها منفی یک است.',f'-1/Rational({k})')
 b.n(3,'حل دستگاه با ضرایب نابرابر',u,f'در دستگاه 2x+3y={2*a+3*z} و 3x−y={3*a-z}، x چند است؟',a,'یکی از معادله‌ها را طوری ضرب کن که یک مجهول حذف شود؛ جواب را در هر دو بررسی کن.',f'(({2*a+3*z})+3*({3*a-z}))/11')
 b.n(3,'مدل‌سازی مجموع و اختلاف سن',u,f'مجموع سن دو نفر {2*a+20} و اختلاف سن آن‌ها 20 سال است؛ سن فرد کوچک‌تر چند سال است؟',a,'دو معادلهٔ مجموع و اختلاف بنویس؛ کم کردن آن‌ها دو برابر سن کوچک‌تر را می‌دهد.',f'({2*a+20}-20)/2')
 b.n(3,'مدل‌سازی دو نوع کالا',u,f'جمعاً {a+z} بلیت کودک و بزرگسال فروخته شده؛ کودک {k} و بزرگسال {k+2} واحد است؛ درآمد {a*k+z*(k+2)} واحد است؛ چند بلیت بزرگسال فروخته شده؟',z,'تعداد کل و درآمد کل دو معادلهٔ مستقل می‌دهند.',f'({a*k+z*(k+2)}-{k}*{a+z})/2')
 b.n(3,'آستانهٔ برابری دو تعرفه',t,f'هزینهٔ طرح A برابر {a}+{k}x و طرح B برابر {a+2*z}+{k-1}x است؛ در چه x هزینه‌ها برابرند؟',2*z,'در نقطهٔ تغییر به‌صرفه بودن، دو هزینه را مساوی بگذار.',f'({a+2*z}-{a})/({k}-({k-1}))')
 b.n(3,'طول و عرض ثابت در دستگاه ویژه',u,f'دستگاه x={a} و y={z} چه عرضی برای نقطهٔ جواب می‌دهد؟',z,'دو خط یکی عمودی و دیگری افقی‌اند و تقاطعشان همین زوج مرتب است.',f'{z}')
 b.m(3,'دستگاه ناسازگار از ضریب‌های متناسب',u,f'دستگاه x+y={a} و 2x+2y={2*a+1} چند جواب دارد؟','هیچ جواب ندارد',['یک جواب','بی‌شمار جواب',str(a)],'سمت چپ معادلهٔ دوم دو برابر اولی است ولی سمت راست نیست؛ دو خط موازی و جدا هستند.')
 b.n(4,'سه خط هم‌گذر و پارامتر',u,f'دو خط y=x+{a} و y=−x+{a+2*z} در نقطه‌ای برخورد می‌کنند؛ اگر خط y=2x+c هم از آن نقطه بگذرد، c چند است؟',a-z,'ابتدا نقطهٔ برخورد دو خط نخست را پیدا کن و در خط سوم جایگذاری کن.',f'({a}+{z})-2*{z}')
 b.n(4,'پارامتر لازم برای بی‌شمار جواب',u,f'برای اینکه دستگاه y={k}x+{a} و {k+1}y={k*(k+1)}x+c بی‌شمار جواب داشته باشد، c چند است؟',(k+1)*a,'همهٔ ضریب‌ها و ثابت‌ها باید با یک نسبت تغییر کرده باشند.',f'({k+1})*{a}')
 b.n(4,'پارامتر دستگاه با جواب مشخص',u,f'دستگاه px+y={a*k+z} و x+y={a+z} جواب x={a}، y={z} دارد؛ p چند است؟',k,'جواب مشترک داده‌شده را در معادلهٔ دارای پارامتر بگذار.',f'({a*k+z}-{z})/{a}')
 b.n(4,'مساحت از خط و توازی',t,f'خطی موازی y=−x از نقطهٔ ({a},{z}) می‌گذرد؛ مساحت مثلثِ خط و دو محور چند است؟',F((a+z)**2,2),'معادلهٔ خط y=−x+b و b=a+z است؛ دو عرض از مبدأ برابر می‌شوند.',f'({a}+{z})**2/2')
 b.n(4,'دستگاه دو کسر خطی',u,f'در دستگاه x/2+y/3={frac(a,2)+"+"+frac(z,3)} و x−y={a-z}، x چند است؟',a,'ابتدا مخرج‌های عددی را حذف کن؛ سپس دستگاه خطی را حل کن.',f'((Rational({a},2)+Rational({z},3))*6+2*({a-z}))/5')
 b.n(4,'یافتن زمان با مدل دو حرکت',u,f'دو نفر هم‌زمان از یک نقطه با سرعت {k+2} و {k} متر بر ثانیه در یک جهت حرکت می‌کنند؛ پس از چند ثانیه فاصله‌شان {2*z} متر می‌شود؟',z,'در حرکت هم‌جهت، فاصله با اختلاف سرعت‌ها زیاد می‌شود.',f'{2*z}/(({k+2})-{k})')
 b.n(4,'کاهش بودجهٔ خطی با دو هزینه',t,f'از {a+5*k} واحد بودجه، ابتدا {a} واحد هزینهٔ ثابت و سپس برای هر ساعت {k} واحد کم می‌شود؛ چند ساعت بعد بودجه صفر است؟',5,'مقدار باقیمانده را صفر قرار بده؛ هزینهٔ ثابت را دوبار حساب نکن.',f'({a+5*k}-{a})/{k}')
 b.n(4,'نقطهٔ مشترک با شرط مجموع مختصات',u,f'نقطه‌ای روی y={k}x+{a} است و مجموع طول و عرض آن {a+(k+1)*z} است؛ طول آن چند است؟',z,'شرط مجموع، معادلهٔ دوم دستگاه است؛ y را جایگذاری کن.',f'({a+(k+1)*z}-{a})/({k}+1)')
 b.n(4,'شرط عمود بودن با پارامتر کسری',s,f'شیب خط اول −{k} و شیب خط دوم p/{a} است؛ اگر عمود باشند، p چند است؟',F(a,k),'حاصل ضرب شیب‌ها را منفی یک قرار بده؛ علامت‌ها را دقیق نگه دار.',f'Rational({a},{k})')
 b.m(4,'تفسیر هندسی جواب‌های دستگاه',u,'اگر هر جواب یک معادله، معادلهٔ دوم را هم برآورده کند و هر دو معادله خط راست باشند، چه نتیجه‌ای لازم است؟','دو خط منطبق‌اند',['حتماً عمودند','حتماً موازی و جدا هستند','تنها مبدأ مشترک است'],'یک خط نمی‌تواند بی‌شمار نقطه از خطی متفاوت داشته باشد؛ پس هر دو یک خط را توصیف می‌کنند.')
 b.essay(2,'رسم نمودار با دو نقطه و کنترل',t,f'خط y={k}x−{a} را با جدول دو نقطه رسم کن و محل برخورد با محور عرض‌ها را مشخص کن.',f'برای x=0، y=−{a} و برای x=1، y={k-a} است؛ دو نقطه را وصل کن و عرض از مبدأ −{a} است.',['دو مختصات درست.','محورهای مدرج و رسم خط.','مشخص کردن عرض از مبدأ.'])
 b.essay(3,'حل تشریحی دستگاه با کنترل دو معادله',u,f'دستگاه x+y={a+z} و 2x−y={2*a-z} را حل و جواب را کنترل کن.',f'با جمع دو معادله 3x={3*a} و x={a}؛ سپس y={z}؛ هر دو تساوی با این زوج برقرارند.',['روش حذف یا جایگذاری معتبر.','هر دو مجهول.','بررسی در هر دو معادله.'])
 b.essay(3,'استدلال نابرابری شیب و ضریب ظاهر',s,f'چرا در معادلهٔ 3y−{3*k}x={a} نمی‌توان −{3*k} را شیب خط دانست؟',f'باید y تنها شود؛ y={k}x+{frac(a,3)}، پس شیب {k} است.',['تبدیل به فرم استاندارد.','شیب و عرض از مبدأ درست.'])
 b.essay(4,'مدل‌سازی و تفسیر دستگاه هزینه',u,'یک مسئلهٔ دو نوع کالا بساز که با دستگاه دو معادلهٔ خطی حل شود و معنی هر مجهول و هر معادله را توضیح بده.','برای نمونه تعداد دو کالا x,y؛ معادلهٔ نخست تعداد کل و معادلهٔ دوم جمع هزینه‌ها را بیان می‌کند؛ جواب باید نامنفی و با واحد سازگار باشد.',['تعریف مجهول‌ها.','دو رابطهٔ مستقل.','حل و تفسیر منطقی جواب.'])
 for q in b.rows:
  adjusted={'کاهش بودجهٔ خطی با دو هزینه': 2, 'یافتن زمان با مدل دو حرکت': 3}.get(q['objective'])
  if adjusted:q['level']=adjusted;q['difficulty']=LEVELS[adjusted-1]
 return b.finish()
